/* From Uiverse.io by sabin-koju - Tags: switch, toggle, toggle switch */
.__UIV_SCOPE__ .switch {
  display: -ms-inline-flexbox;
  display: inline-flex;
  -ms-flex-align: center;
  align-items: center;
}

.__UIV_SCOPE__ .switch .switch-label {
  cursor: pointer;
}

.__UIV_SCOPE__ .switch .switch-input {
  appearance: none;
  display: -ms-inline-flexbox;
  display: inline-flex;
  -ms-flex-align: center;
  align-items: center;
  box-shadow: inset 0 0 0 1px #c9c9c9;
  background-color: #dadada;
  width: 3rem;
  min-width: 3rem;
  padding: 0.125rem;
  border-radius: 3rem;
  cursor: pointer;
  transition: background-color 0.75s ease, box-shadow 0.35s ease-in;
}

.__UIV_SCOPE__ .switch .switch-input:before {
  position: relative;
  content: "";
  display: inline-block;
  border-radius: 1rem;
  height: 1.5rem;
  width: 1.5rem;
  box-shadow: 0 0 3px rgba(0, 0, 0, 0.32);
  background-color: #ffffff;
  border: 1px solid rgba(0, 0, 0, 0);
  transition: all 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.175);
}

.__UIV_SCOPE__ .switch .switch-input:active:not(:disabled):before {
  width: 1.75rem;
}

.__UIV_SCOPE__ .switch .switch-input:hover:not(:disabled) {
  box-shadow: inset 0 0 0 1rem #c9c9c9;
}

.__UIV_SCOPE__ .switch .switch-input:focus, .__UIV_SCOPE__ .switch .switch-input:focus-within {
  box-shadow: 0 0 0 0.125rem #4caf30;
  outline: none;
}

.__UIV_SCOPE__ .switch .switch-input:focus:before, .__UIV_SCOPE__ .switch .switch-input:focus-within:before {
  box-shadow: 0 0 4px 1px rgba(0, 0, 0, 0.4);
}

.__UIV_SCOPE__ .switch .switch-input:checked {
  background-color: #5dca3e;
  box-shadow: inset 0 0 0 1px #5dca3e;
}

.__UIV_SCOPE__ .switch .switch-input:checked:before {
  transform: translate3d(calc(100% - 0.5rem), 0, 0);
}

.__UIV_SCOPE__ .switch .switch-input:checked:active:not(:disabled):before {
  margin-left: -0.5rem;
}

.__UIV_SCOPE__ .switch .switch-input:checked:hover:not(:disabled) {
  box-shadow: inset 0 0 0 1rem #459f2c;
}

.__UIV_SCOPE__ .switch .switch-input:checked:focus, .__UIV_SCOPE__ .switch .switch-input:checked:focus-within {
  box-shadow: 0 0 0 0.125rem #4caf30;
}

.__UIV_SCOPE__ .switch .switch-input:disabled {
  pointer-events: none;
  cursor: not-allowed;
  opacity: 0.5;
  user-select: none;
}

.__UIV_SCOPE__ .switch .switch-input:disabled:before {
  background-color: #f8f8f8;
}
